param(
    [string]$Compiler = '',
    [ValidateRange(8, 1024)][int]$Scale = 64,
    [ValidateRange(1, 256)][int]$Jobs = 20,
    [int]$Seed = 424242,
    [string]$OutputDir = ''
)
$ErrorActionPreference = 'Stop'
$repo = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'))
if (!$Compiler) { $Compiler = Join-Path $repo 'bootstrap_compiler/out/boot.exe' }
$Compiler = (Resolve-Path -LiteralPath $Compiler).Path
if (!$OutputDir) { $OutputDir = Join-Path $PSScriptRoot ('.runs/industrial-' + (Get-Date -Format 'yyyyMMdd-HHmmss-fff')) }
$OutputDir = [IO.Path]::GetFullPath($OutputDir)
if (Test-Path -LiteralPath $OutputDir) { throw "Refusing to overwrite existing output: $OutputDir" }
New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
function Write-Utf8NoBom([string]$Path, [string]$Text) { [IO.File]::WriteAllText($Path, $Text, [Text.UTF8Encoding]::new($false)) }
function New-Fixture([string]$Root, [int]$Count, [int]$FixtureSeed) {
    New-Item -ItemType Directory -Path (Join-Path $Root 'src') -Force | Out-Null
    $rng = [Random]::new($FixtureSeed); $sources = [Collections.Generic.List[string]]::new(); $imports = [Collections.Generic.List[string]]::new(); $calls = [Collections.Generic.List[string]]::new(); $expected = 0L
    for ($index = 0; $index -lt $Count; $index++) {
        $suffix = $index.ToString('D3'); $path = Join-Path $Root ("src/unit$suffix.vyx"); $sources.Add('"src/unit' + $suffix + '.vyx"'); $imports.Add('use Industrial.Unit' + $suffix + ';')
        $delta = 1 + $rng.Next(1, 97); $expected = ($expected + (16L * $delta)) % 1000003L
        $steps = [Collections.Generic.List[string]]::new(); for ($step = 0; $step -lt 16; $step++) { $steps.Add('    value = (value + ' + $delta + ') % 1000003;') }
        $head = @((('module Industrial.Unit' + $suffix + ';')),'',('public fn compute' + $suffix + '(seed: i64) -> i64 {'),'    var value = seed;') -join "`n"; $tail = @('    return value;','}') -join "`n"; $body = $head + "`n" + ($steps -join "`n") + "`n" + $tail
        Write-Utf8NoBom $path $body; $calls.Add('    result = compute' + $suffix + '(result);')
    }
    $generic = @('module Industrial.Generic;','','public class Cell<T> {','    public value: T;','    public static fn make(value: T) -> Cell<T> {','        return Cell::<T> { value: value };','    }','    public fn get(self) -> T { return self.value; }','}')
    Write-Utf8NoBom (Join-Path $Root 'src/generic.vyx') ($generic -join "`n")
    $traits = @('module Industrial.Traits;','','interface Shape {','    fn area(self) -> i32;','}','','class Circle {','    public r: i32;','    public fn area(self) -> i32 { return self.r * self.r; }','}','','impl Shape for Circle {','    fn area(self) -> i32 { return self.r * self.r; }','}','','fn go(x: &dyn Shape) -> i32 { return x.area(); }','','public fn trait_probe() -> i32 {','    let c = Circle { r: 3 };','    return go(&c);','}')
    Write-Utf8NoBom (Join-Path $Root 'src/traits.vyx') ($traits -join "`n"); $sources.Add('"src/generic.vyx"'); $sources.Add('"src/traits.vyx"'); $imports.Add('use Industrial.Traits;')
    $inlineGeneric = @('','class Cell<T> {','    public value: T;','    public static fn make(value: T) -> Cell<T> {','        return Cell::<T> { value: value };','    }','    public fn get(self) -> T { return self.value; }','}')
    $main = @('module Industrial;') + $imports + $inlineGeneric + @('','fn main() -> i32 {','    var result: i64 = 0;') + $calls + @('    let cell = Cell::<i64>.make(42);','    result = result + cell.get() + (trait_probe() as i64);',('    if (result != ' + ($expected + 51) + ') { return 1; }'),'    return 0;','}')
    Write-Utf8NoBom (Join-Path $Root 'src/main.vyx') ($main -join "`n")
    $manifest = @('[package]','name = "industrial_pressure"','version = "0.1.0"','entry = "src/main.vyx"','','[build]','cache_dir = ".cache"','output_dir = "target"','parallel_vyx = true','mir_partition = false','','[target.industrial]','type = "executable"','entry = "src/main.vyx"',('sources = [' + ($sources -join ', ') + ']'))
    Write-Utf8NoBom (Join-Path $Root 'Vyx.toml') ($manifest -join "`n")
    $negative = @('module Industrial.Negative;','fn main() -> i32 {','    let bad: i32 = "this must fail";','    return bad;','}')
    Write-Utf8NoBom (Join-Path $Root 'negative.vyx') ($negative -join "`n")
    Write-Utf8NoBom (Join-Path $Root 'fixture.json') ([ordered]@{ seed = $FixtureSeed; scale = $Count; expected = ($expected + 51) } | ConvertTo-Json)
}
function Get-DescendantIds([int]$RootPid) {
    try { $all = @(Get-CimInstance Win32_Process -ErrorAction Stop); $children = @{}; foreach ($row in $all) { $parent = [int]$row.ParentProcessId; if (!$children.ContainsKey($parent)) { $children[$parent] = [Collections.Generic.List[int]]::new() }; $children[$parent].Add([int]$row.ProcessId) }; $ids = [Collections.Generic.List[int]]::new(); $queue = [Collections.Generic.Queue[int]]::new(); $queue.Enqueue($RootPid); while ($queue.Count -gt 0) { $id = $queue.Dequeue(); $ids.Add($id); if ($children.ContainsKey($id)) { foreach ($child in $children[$id]) { $queue.Enqueue($child) } } }; return $ids.ToArray() } catch { return @($RootPid) }
}
function Get-ArtifactDigest([string]$Root) {
    $rows = [Collections.Generic.List[string]]::new(); $cache = Join-Path $Root '.cache'; if (Test-Path -LiteralPath $cache) { $files = @(Get-ChildItem -LiteralPath $cache -Recurse -File | Where-Object { $_.Name -match '\.obj$|\.cgu\.|\.cgu\.list$' } | Sort-Object FullName); foreach ($file in $files) { $rel = $file.FullName.Substring($Root.Length).TrimStart('\','/'); $hash = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash; $rows.Add("$rel=$hash") } }; $bytes = [Text.UTF8Encoding]::new($false).GetBytes(($rows -join "`n")); $sha = [Security.Cryptography.SHA256]::Create(); try { return ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
}
function Invoke-Build([string]$Root, [string]$Label, [int]$WorkerCount) {
    $out = Join-Path $Root ("$Label.stdout.log"); $err = Join-Path $Root ("$Label.stderr.log"); $old = @{}; foreach ($name in @('LLVM_ROOT','VYX_BUILD_PROFILE','VYX_BUILD_TRACE','VYX_BUILD_USE_TASK_TIMES','VYX_COLOR')) { $old[$name] = [Environment]::GetEnvironmentVariable($name) }; $env:LLVM_ROOT = Join-Path $repo 'clang'; $env:VYX_BUILD_PROFILE = '1'; $env:VYX_BUILD_TRACE = '1'; $env:VYX_BUILD_USE_TASK_TIMES = '1'; $env:VYX_COLOR = '0'; $sw = [Diagnostics.Stopwatch]::StartNew(); $proc = Start-Process -FilePath $Compiler -ArgumentList @('build','--target','industrial',("-j$WorkerCount")) -WorkingDirectory $Root -RedirectStandardOutput $out -RedirectStandardError $err -PassThru -WindowStyle Hidden; $peakBytes = 0L; $peakChildren = 0; while (!$proc.HasExited) { $ids = @(Get-DescendantIds $proc.Id); if ($ids.Count -gt $peakChildren) { $peakChildren = $ids.Count }; $sum = 0L; foreach ($id in $ids) { try { $sum += [int64](Get-Process -Id $id -ErrorAction Stop).WorkingSet64 } catch {} }; if ($sum -gt $peakBytes) { $peakBytes = $sum }; Start-Sleep -Milliseconds 100; $proc.Refresh() }; $proc.WaitForExit(); $proc.Refresh(); $buildExit = [int]$proc.ExitCode; $sw.Stop(); foreach ($name in $old.Keys) { [Environment]::SetEnvironmentVariable($name, $old[$name]) }; $text = ''; if (Test-Path $out) { $text += Get-Content -LiteralPath $out -Raw }; if (Test-Path $err) { $text += Get-Content -LiteralPath $err -Raw }; $log = Join-Path $Root "$Label.log"; Write-Utf8NoBom $log $text; $compileCount = ([regex]::Matches($text, '(?m)^\[\d+/\d+\] compile ')).Count; $activePeak = 0; foreach ($match in [regex]::Matches($text, 'active=(\d+)')) { $activePeak = [Math]::Max($activePeak,[int]$match.Groups[1].Value) }; $reserveBytes = -1L; $reserveMatch = [regex]::Match($text, 'reserve_bytes=(-?\d+)'); if ($reserveMatch.Success) { $reserveBytes = [int64]$reserveMatch.Groups[1].Value }; $exe = Join-Path $Root 'target/industrial.exe'; $runExit = -1; if ($buildExit -eq 0 -and (Test-Path $exe)) { & $exe *> (Join-Path $Root "$Label.run.log"); $runExit = $LASTEXITCODE }; [pscustomobject]@{ label=$Label; jobs=$WorkerCount; exit=$buildExit; run_exit=$runExit; wall_s=[Math]::Round($sw.Elapsed.TotalSeconds,3); peak_tree_rss_mib=[Math]::Round($peakBytes/1MB,1); peak_tree_processes=$peakChildren; scheduler_active_peak=$activePeak; reserve_bytes=$reserveBytes; compile_tasks=$compileCount; artifacts=Get-ArtifactDigest $Root; executable_sha256=if(Test-Path $exe){(Get-FileHash $exe -Algorithm SHA256).Hash}else{''}; log=$log }
}
function Copy-Fixture([string]$Source, [string]$Destination) { New-Item -ItemType Directory -Path $Destination -Force | Out-Null; Copy-Item (Join-Path $Source 'Vyx.toml') $Destination; Copy-Item (Join-Path $Source 'fixture.json') $Destination; Copy-Item (Join-Path $Source 'negative.vyx') $Destination; Copy-Item (Join-Path $Source 'src') $Destination -Recurse }
$fixture = Join-Path $OutputDir 'fixture'; New-Fixture $fixture $Scale $Seed; $matrix = [Collections.Generic.List[object]]::new(); foreach ($entry in @(@('j1',1),@('jN',$Jobs))) { $tag=$entry[0]; $workerCount=[int]$entry[1]; $project=Join-Path $OutputDir $tag; Copy-Fixture $fixture $project; $matrix.Add((Invoke-Build $project "$tag-cold" $workerCount)); $matrix.Add((Invoke-Build $project "$tag-warm" $workerCount)); $unit=Join-Path $project 'src/unit000.vyx'; $body=Get-Content $unit -Raw; Write-Utf8NoBom $unit ($body + "`n// deterministic incremental edit seed" + $Seed + "`n"); $matrix.Add((Invoke-Build $project "$tag-incremental" $workerCount)) }
$negativeProject=Join-Path $OutputDir 'negative'; Copy-Fixture $fixture $negativeProject; $negOut=Join-Path $negativeProject 'negative.obj'; $negText=& $Compiler '--src=file' (Join-Path $negativeProject 'negative.vyx') '--emit=obj' '-o' $negOut 2>&1 | Out-String; $negExit=$LASTEXITCODE; Write-Utf8NoBom (Join-Path $negativeProject 'negative.log') $negText; $negativeDiagnostic=($negExit -ne 0 -and $negText -match '(?i)(E\d{4}|error)');
$genericProject=Join-Path $OutputDir 'cross-module-generic'; New-Item -ItemType Directory -Path (Join-Path $genericProject 'interfaces/Industrial') -Force | Out-Null; Copy-Item (Join-Path $fixture 'src/generic.vyx') (Join-Path $genericProject 'generic.vyx'); $genericConsumer=@('module Industrial.Consumer;','use Industrial.Generic;','','fn main() -> i32 {','    let c = Cell::<i64>.make(42);','    return c.get() - 42;','}'); Write-Utf8NoBom (Join-Path $genericProject 'consumer.vyx') ($genericConsumer -join "`n"); $genericEmit=& $Compiler '--src=file' (Join-Path $genericProject 'generic.vyx') '--emit=vyi' '--vyi-shallow' '-o' (Join-Path $genericProject 'interfaces/Industrial/Generic.vyi') 2>&1 | Out-String; $genericEmitExit=$LASTEXITCODE; $genericUse=''; $genericUseExit=-1; if($genericEmitExit -eq 0){$genericUse=& $Compiler '--src=file' (Join-Path $genericProject 'consumer.vyx') '--interface-root' (Join-Path $genericProject 'interfaces') '--emit=exe' '-o' (Join-Path $genericProject 'consumer.exe') 2>&1 | Out-String; $genericUseExit=$LASTEXITCODE; if($genericUseExit -eq 0){& (Join-Path $genericProject 'consumer.exe') *> (Join-Path $genericProject 'consumer.run.log'); $genericUseExit=$LASTEXITCODE}}; Write-Utf8NoBom (Join-Path $genericProject 'emit.log') $genericEmit; Write-Utf8NoBom (Join-Path $genericProject 'consumer.log') $genericUse; $genericStatus=if($genericUseExit -eq 0){'PASS'}else{'FAIL'}; Write-Utf8NoBom (Join-Path $genericProject 'result.json') ([ordered]@{emit_exit=$genericEmitExit;consumer_exit=$genericUseExit;status=$genericStatus}|ConvertTo-Json); $rows=@($matrix); $failures=[Collections.Generic.List[string]]::new(); foreach($row in $rows){if($row.exit -ne 0 -or $row.run_exit -ne 0){$failures.Add("$($row.label): build/run failed")}}; foreach($tag in @('j1','jN')){$cold=$rows|Where-Object label -eq "$tag-cold";$warm=$rows|Where-Object label -eq "$tag-warm";$inc=$rows|Where-Object label -eq "$tag-incremental";if($warm.compile_tasks -ne 0){$failures.Add("$tag warm build compiled $($warm.compile_tasks) tasks")};if($cold.reserve_bytes -ne 3221225472){$failures.Add("$tag reserve_bytes=$($cold.reserve_bytes), expected 3221225472")};if($warm.artifacts -ne $cold.artifacts){$failures.Add("$tag warm artifact digest changed")};if($inc.compile_tasks -le 0 -or $inc.compile_tasks -ge $cold.compile_tasks){$failures.Add("$tag incremental invalidation count=$($inc.compile_tasks) cold=$($cold.compile_tasks)")}}; $jNCold=$rows|Where-Object label -eq 'jN-cold';if($Jobs -gt 1 -and $jNCold.scheduler_active_peak -lt 2){$failures.Add("-j$Jobs showed no scheduler fanout")};if(!$negativeDiagnostic){$failures.Add('negative source was accepted or lacked E####/error diagnostic')}; if($genericStatus -ne 'PASS'){$failures.Add('cross-module generic template consumer failed')}; Write-Utf8NoBom (Join-Path $OutputDir 'report.json') ([ordered]@{compiler=$Compiler;seed=$Seed;scale=$Scale;jobs=$Jobs;fixture=$fixture;negative_exit=$negExit;negative_diagnostic=$negativeDiagnostic;cross_module_generic=$genericStatus;results=$rows;failures=$failures}|ConvertTo-Json -Depth 8); $rows|Format-Table label,jobs,exit,run_exit,wall_s,peak_tree_rss_mib,peak_tree_processes,scheduler_active_peak,reserve_bytes,compile_tasks -AutoSize; if($failures.Count -gt 0){Write-Error (($failures|ForEach-Object{"FAIL: $_"}) -join "`n");exit 1}; Write-Output "compiler-industrial: seed=$Seed scale=$Scale j1/j$Jobs cold-warm-incremental + generic/trait + negative diagnostic OK"
